{
  "packet_id": "H6-T02-3",
  "claim_id": "C020",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C020.component",
    "value": "Exposed exports that remain unfinished must be explicitly censored.",
    "scope": "Endpoint and follow-up handling; following exposed exports to completion is qualified by feasibility.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P017 directly specifies explicit censoring of unfinished exports and qualifies completion follow-up by feasibility."
    }
  },
  "signal_basis": {
    "component_id": "C020.signal_basis",
    "value": "Some exposed exports remain unfinished when their available follow-up ends, while time-to-completion estimates must include unfinished exports.",
    "scope": "Handling incomplete completion times after the planned endpoint and feasible follow-up; the measurements are proposed and their occurrence is assumed for this judgment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P017 supplies the endpoint, feasible follow-up, and unfinished-export condition; P021 requires completion-time estimates to include unfinished exports. P025 establishes that these are proposed measurements."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C020.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without an unresolved empirical relation."
    }
  },
  "rationale": "An export still unfinished at the end of its observed follow-up has an unknown completion time exceeding its observed elapsed time. Explicit censoring faithfully represents that incomplete observation and supports including it in completion-time analysis. This licenses the specified handling within its feasibility qualification.",
  "uncertainty": "Censoring records incomplete outcomes; it does not by itself guarantee unbiased completion-time estimates.",
  "anomalies": []
}
